(()=>{const bs=T.BattleScene;const out={};const fails=[];const CHK=(k,v)=>{out[k]=v;if(v!==true)fails.push(k+':'+JSON.stringify(v));};
// 注入测试事件页到 troop16: 回合2(第2回合)时 333 消灭敌索引3(兵士)
const pages=T.$dataTroops[16].pages||[];
pages.push({conditions:{actorHp:50,actorId:1,actorValid:false,enemyHp:50,enemyIndex:0,enemyValid:false,switchId:1,switchValid:false,turnA:2,turnB:2,turnEnding:false,turnValid:true},span:0,list:[{code:333,indent:0,parameters:[3,0,0]},{code:0,indent:0,parameters:[]}]});
