CHK('onceOnly',out.after2===after);
// 恢复敌人(334出现)验证
bs.troop.members[3].appear();bs.troop.members[3].revive();
out.revived=bs.troop.aliveMembers().length;
CHK('appearRevive',out.revived===before);
// 空条件页(无条件)在回合1执行——用第0页(已执行)验证不重复
pages.push({conditions:{actorHp:50,actorId:1,actorValid:false,enemyHp:50,enemyIndex:0,enemyValid:false,switchId:1,switchValid:false,turnA:1,turnB:1,turnEnding:false,turnValid:true},span:0,list:[{code:122,indent:0,parameters:[99,99,0,0,777]},{code:0,indent:0,parameters:[]}]});
const idx2=pages.length-1;
bs.troop.turnCount=0;bs.runTroopEvents();
out.var99=T.$gameVariables.value(99);
CHK('varScript',out.var99===777&&bs._battleEventsDone.has(idx2));
out.allOk=fails.length===0;out.fails=fails;
return JSON.stringify(out);})()
